/* Independent review serializer. Deliberately not imported into the Next app. */
const {Fragment}=require('./register.cjs');
const esc=value=>String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const voids=new Set(['area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr']);
const bools=new Set(['hidden','disabled','checked','selected','multiple','required','autoFocus','readOnly','open','noValidate']);
const names={className:'class',htmlFor:'for',tabIndex:'tabindex',autoFocus:'autofocus',autoComplete:'autocomplete',readOnly:'readonly',noValidate:'novalidate',maxLength:'maxlength',colSpan:'colspan',rowSpan:'rowspan',strokeWidth:'stroke-width',strokeLinecap:'stroke-linecap',strokeLinejoin:'stroke-linejoin',fillRule:'fill-rule',clipRule:'clip-rule',crossOrigin:'crossorigin'};
function render(node){if(node==null||typeof node==='boolean')return '';if(typeof node==='string'||typeof node==='number')return esc(node);if(Array.isArray(node))return node.map(render).join('');if(node.type===Fragment)return render(node.props.children);if(typeof node.type==='function')return render(node.type(node.props));if(typeof node.type!=='string')throw new TypeError('Unsupported review element');const {children,dangerouslySetInnerHTML,...props}=node.props;let attrs='';for(const [key,value]of Object.entries(props)){if(key==='key'||key==='ref'||key==='suppressHydrationWarning'||key.startsWith('on')||value==null)continue;if(bools.has(key)){if(value)attrs+=' '+(names[key]||key);continue}if(key==='style'){const style=Object.entries(value).map(([k,v])=>`${k.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())}:${typeof v==='number'&&!['opacity','zIndex','fontWeight','flex','order'].includes(k)?v+'px':v}`).join(';');attrs+=' style="'+esc(style)+'"';continue}attrs+=' '+(names[key]||key)+'="'+esc(value)+'"'}const start='<'+node.type+attrs+'>';return voids.has(node.type)?start:start+(dangerouslySetInnerHTML?dangerouslySetInnerHTML.__html:render(children))+'</'+node.type+'>'}
module.exports={render,esc};
